  5261	
  5262	/* Eat from start of current (textual) block any reference definitions and
  5263	 * remember them so we can resolve any links referring to them.
  5264	 *
  5265	 * (Reference definitions can only be at start of it as they cannot break
  5266	 * a paragraph.)
  5267	 */
  5268	static int
  5269	md_consume_link_reference_definitions(MD_CTX* ctx)
  5270	{
  5271	    MD_LINE* lines = (MD_LINE*) (ctx->current_block + 1);
  5272	    MD_SIZE n_lines = ctx->current_block->n_lines;
  5273	    MD_SIZE n = 0;
  5274	
  5275	    /* Compute how many lines at the start of the block form one or more
  5276	     * reference definitions. */
  5277	    while(n < n_lines) {
  5278	        int n_link_ref_lines;
  5279	
  5280	        n_link_ref_lines = md_is_link_reference_definition(ctx,
  5281	                                    lines + n, n_lines - n);
  5282	        /* Not a reference definition? */
  5283	        if(n_link_ref_lines == 0)
  5284	            break;
  5285	
  5286	        /* We fail if it is the ref. def. but it could not be stored due
  5287	         * a memory allocation error. */
  5288	        if(n_link_ref_lines < 0)
  5289	            return -1;
  5290	
  5291	        n += n_link_ref_lines;
  5292	    }
  5293	
  5294	    /* If there was at least one reference definition, we need to remove
  5295	     * its lines from the block, or perhaps even the whole block. */
  5296	    if(n > 0) {
  5297	        if(n == n_lines) {
  5298	            /* Remove complete block. */
  5299	            ctx->n_block_bytes -= n * sizeof(MD_LINE);
  5300	            ctx->n_block_bytes -= sizeof(MD_BLOCK);
  5301	            ctx->current_block = NULL;
  5302	        } else {
  5303	            /* Remove just some initial lines from the block. */
  5304	            memmove(lines, lines + n, (n_lines - n) * sizeof(MD_LINE));
  5305	            ctx->current_block->n_lines -= n;
  5306	            ctx->n_block_bytes -= n * sizeof(MD_LINE);
  5307	        }
  5308	    }
  5309	
  5310	    return 0;
  5311	}
  5312	
  5313	static int
  5314	md_end_current_block(MD_CTX* ctx)
  5315	{
  5316	    int ret = 0;
  5317	
  5318	    if(ctx->current_block == NULL)
  5319	        return ret;
  5320	
  5321	    /* Check whether there is a reference definition. (We do this here instead
  5322	     * of in md_analyze_line() because reference definition can take multiple
  5323	     * lines.) */
  5324	    if(ctx->current_block->type == MD_BLOCK_P  ||
  5325	       (ctx->current_block->type == MD_BLOCK_H  &&  (ctx->current_block->flags & MD_BLOCK_SETEXT_HEADER)))
  5326	    {
  5327	        MD_LINE* lines = (MD_LINE*) (ctx->current_block + 1);
  5328	        if(lines[0].beg < ctx->size  &&  CH(lines[0].beg) == _T('[')) {
  5329	            MD_CHECK(md_consume_link_reference_definitions(ctx));
  5330	            if(ctx->current_block == NULL)
  5331	                return ret;
  5332	        }
  5333	    }
  5334	
  5335	    if(ctx->current_block->type == MD_BLOCK_H  &&  (ctx->current_block->flags & MD_BLOCK_SETEXT_HEADER)) {
  5336	        MD_SIZE n_lines = ctx->current_block->n_lines;
  5337	
  5338	        if(n_lines > 1) {
  5339	            /* Get rid of the underline. */
  5340	            ctx->current_block->n_lines--;
  5341	            ctx->n_block_bytes -= sizeof(MD_LINE);
  5342	        } else {
  5343	            /* Only the underline has left after eating the ref. defs.
  5344	             * Keep the line as beginning of a new ordinary paragraph. */
  5345	            ctx->current_block->type = MD_BLOCK_P;
  5346	            return 0;
  5347	        }
  5348	    }
  5349	
  5350	    /* Mark we are not building any block anymore. */
  5351	    ctx->current_block = NULL;
  5352	
  5353	abort:
  5354	    return ret;
  5355	}
